import javax.imageio.ImageIO;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;

/**
 * Draws curseforge/icon.png from scratch: a white border, a night sky with a faint nebula and stars made from noise,
 * "JET / FLIGHT" in hand-made pixel letters, and two exhaust flames under the words. No font, no Ad Astra asset,
 * nothing generated by AI.
 * Run from the repo root: java curseforge/MakeIcon.java curseforge/icon.png [preview64.png]
 */
public class MakeIcon {
    static final int GRID = 52;
    static final int CELL = 10;
    static final int BORDER = 2;
    static final long SEED = 2026_1107L;

    static final int WHITE = 0xFFFFFF;
    static final int OUTLINE = 0x070814;
    static final int SHADOW = 0x0E1028;
    /** Sky tones, darkest to lightest (nebula). */
    static final int[] SKY = {0x05060F, 0x0A0D22, 0x111637, 0x1C1E4C, 0x2B2563, 0x3E2F78};
    static final int[] STARS = {0x8A93C8, 0xC9D2FF, 0xFFFFFF};
    /** Flame tones, hottest first. */
    static final int[] FLAME = {0xFFF6C8, 0xFFE066, 0xFFB12E, 0xF2741B, 0xC9401A, 0x7A1E16};

    static final String[] J = {
            "######",
            "######",
            "....##",
            "....##",
            "....##",
            "....##",
            "....##",
            "##..##",
            "##..##",
            "######",
            ".####."};
    static final String[] E = {
            "######",
            "######",
            "##....",
            "##....",
            "##....",
            "#####.",
            "#####.",
            "##....",
            "##....",
            "######",
            "######"};
    static final String[] T = {
            "######",
            "######",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##..",
            "..##.."};
    static final String[] F = {
            "######",
            "######",
            "##....",
            "##....",
            "##....",
            "#####.",
            "#####.",
            "##....",
            "##....",
            "##....",
            "##...."};
    static final String[] L = {
            "##....",
            "##....",
            "##....",
            "##....",
            "##....",
            "##....",
            "##....",
            "##....",
            "##....",
            "######",
            "######"};
    static final String[] I = {
            "####",
            "####",
            ".##.",
            ".##.",
            ".##.",
            ".##.",
            ".##.",
            ".##.",
            ".##.",
            "####",
            "####"};
    static final String[] G = {
            ".#####",
            "######",
            "##....",
            "##....",
            "##....",
            "##.###",
            "##.###",
            "##..##",
            "##..##",
            "######",
            ".#####"};
    static final String[] H = {
            "##..##",
            "##..##",
            "##..##",
            "##..##",
            "######",
            "######",
            "##..##",
            "##..##",
            "##..##",
            "##..##",
            "##..##"};

    public static void main(String[] args) throws Exception {
        int[][] color = new int[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                color[y][x] = sky(x, y);
            }
        }

        int textTop = 7;
        int lineGap = 4;
        int flameTop = textTop + 11 + lineGap + 11 + 2;
        flame(color, 21, flameTop);
        flame(color, 30, flameTop);

        boolean[][] text = new boolean[GRID][GRID];
        stamp(text, new String[][]{J, E, T}, 2, textTop);
        stamp(text, new String[][]{F, L, I, G, H, T}, 2, textTop + 11 + lineGap);

        boolean[][] outline = grow(text);
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x >= 1 && y >= 1 && outline[y - 1][x - 1] && !outline[y][x]) {
                    color[y][x] = SHADOW;
                }
            }
        }
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (text[y][x]) {
                    color[y][x] = WHITE;
                } else if (outline[y][x]) {
                    color[y][x] = OUTLINE;
                }
            }
        }

        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                if (x < BORDER || y < BORDER || x >= GRID - BORDER || y >= GRID - BORDER) {
                    color[y][x] = WHITE;
                }
            }
        }

        BufferedImage image = new BufferedImage(GRID * CELL, GRID * CELL, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < GRID * CELL; y++) {
            for (int x = 0; x < GRID * CELL; x++) {
                image.setRGB(x, y, color[y / CELL][x / CELL]);
            }
        }
        ImageIO.write(image, "png", new File(args[0]));

        if (args.length > 1) {
            BufferedImage small = new BufferedImage(64, 64, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = small.createGraphics();
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g.drawImage(image, 0, 0, 64, 64, null);
            g.dispose();
            ImageIO.write(small, "png", new File(args[1]));
        }
    }

    /** Dark sky with a faint nebula band from noise, and scattered stars. */
    static int sky(int x, int y) {
        double band = 1.0 - Math.abs((x - y * 0.6) - GRID * 0.2) / (GRID * 0.55);
        double cloud = fbm(x / 9.0, y / 9.0, 0);
        double level = cloud * 0.9 + Math.max(0.0, band) * 0.55 - 0.25 + (hash(x, y, 2) - 0.5) * 0.08;
        int index = (int) Math.floor(level * SKY.length);
        index = Math.max(0, Math.min(SKY.length - 1, index));
        double star = hash(x, y, 7);
        if (star > 0.975) {
            return STARS[star > 0.993 ? 2 : star > 0.985 ? 1 : 0];
        }
        return SKY[index];
    }

    /** An exhaust flame pointing down from (cx, top): hot and narrow at the nozzle, flickering and red at the tail. */
    static void flame(int[][] color, int cx, int top) {
        int length = GRID - BORDER - top;
        for (int dy = 0; dy < length; dy++) {
            double t = dy / (double) (length - 1);
            double halfWidth = 2.6 * (1.0 - t * 0.75) + (hash(cx, dy, 9) - 0.5) * 0.9;
            for (int x = cx - 4; x <= cx + 4; x++) {
                double d = Math.abs(x + 0.5 - (cx + 0.5)) / Math.max(0.5, halfWidth);
                if (d > 1.0) {
                    continue;
                }
                double heat = (1.0 - t) * 0.75 + (1.0 - d) * 0.45 + (hash(x, top + dy, 11) - 0.5) * 0.25;
                int index = (int) Math.floor((1.0 - heat) * FLAME.length);
                index = Math.max(0, Math.min(FLAME.length - 1, index));
                color[top + dy][x] = FLAME[index];
            }
        }
    }

    static void stamp(boolean[][] mask, String[][] letters, int gap, int y0) {
        int width = 0;
        for (String[] letter : letters) {
            width += letter[0].length();
        }
        width += gap * (letters.length - 1);
        int x = (GRID - width) / 2;
        for (String[] letter : letters) {
            for (int row = 0; row < letter.length; row++) {
                for (int col = 0; col < letter[row].length(); col++) {
                    if (letter[row].charAt(col) == '#') {
                        mask[y0 + row][x + col] = true;
                    }
                }
            }
            x += letter[0].length() + gap;
        }
    }

    /** The mask plus every cell next to it, diagonals included. */
    static boolean[][] grow(boolean[][] mask) {
        boolean[][] out = new boolean[GRID][GRID];
        for (int y = 0; y < GRID; y++) {
            for (int x = 0; x < GRID; x++) {
                for (int dy = -1; dy <= 1 && !out[y][x]; dy++) {
                    for (int dx = -1; dx <= 1; dx++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && ny >= 0 && nx < GRID && ny < GRID && mask[ny][nx]) {
                            out[y][x] = true;
                            break;
                        }
                    }
                }
            }
        }
        return out;
    }

    static double fbm(double x, double y, int layer) {
        double sum = 0;
        double amplitude = 0.5;
        double total = 0;
        for (int octave = 0; octave < 4; octave++) {
            sum += amplitude * noise(x, y, layer * 16 + octave);
            total += amplitude;
            x *= 2.0;
            y *= 2.0;
            amplitude *= 0.5;
        }
        return sum / total;
    }

    /** Smoothly interpolated value noise in 0..1. */
    static double noise(double x, double y, int layer) {
        int x0 = (int) Math.floor(x);
        int y0 = (int) Math.floor(y);
        double fx = x - x0;
        double fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx);
        double sy = fy * fy * (3 - 2 * fy);
        double a = hash(x0, y0, layer);
        double b = hash(x0 + 1, y0, layer);
        double c = hash(x0, y0 + 1, layer);
        double d = hash(x0 + 1, y0 + 1, layer);
        return (a + (b - a) * sx) * (1 - sy) + (c + (d - c) * sx) * sy;
    }

    static double hash(int x, int y, int layer) {
        long h = SEED ^ (x * 0x9E3779B97F4A7C15L) ^ (y * 0xC2B2AE3D27D4EB4FL) ^ (layer * 0x165667B19E3779F9L);
        h ^= h >>> 33;
        h *= 0xFF51AFD7ED558CCDL;
        h ^= h >>> 33;
        h *= 0xC4CEB9FE1A85EC53L;
        h ^= h >>> 33;
        return (h >>> 11) / (double) (1L << 53);
    }
}
